function Login({done}:{done:()=>void}){const [busy,setBusy]=useState(false),[err,setErr]=useState('');return <div className="login"><section className="login-image"><div className="wordmark">thinkercare<span>TERRAIN</span></div><div className="login-copy"><p className="eyebrow">AU PLUS PRÈS DU TERRAIN</p><h1>Chaque visite.<br/>Une action qui compte.</h1><p>Planifier, animer, suivre.<br/>Le lien entre vos équipes et vos points de vente.</p></div><img src="/assets/scene.jpg" alt="Composition conceptuelle d’un carnet de terrain et d’un présentoir"/><footer>TOUCHÉ <span>•</span> BELNCO <span>•</span> NOOM</footer></section><section className="login-form"><div><div className="symbol"><Icon name="shield" size={28}/></div><h2>Bienvenue sur Terrain</h2><p>Connectez-vous avec votre compte individuel.</p><form onSubmit={async e=>{e.preventDefault();const v=fdata(e);setBusy(true);setErr('');try{await request('',{action:'login',...v});done()}catch(e){setErr((e as Error).message)}finally{setBusy(false)}}}><label>Identifiant<input name="username" required autoComplete="username" placeholder="Votre identifiant"/></label><label>Mot de passe<input name="password" type="password" required autoComplete="current-password" placeholder="Votre mot de passe"/></label>{err&&<Notice error>{err}</Notice>}<button className="primary" disabled={busy}>{busy?'Connexion…':'Ouvrir mon espace'}<Icon name="arrow"/></button></form><small>Accès réservé. Les espaces s’adaptent à votre rôle.</small></div></section></div>}
